// generated from ui.html — do not edit by hand
export default "<!doctype html>\n<html lang=\"en\" dir=\"ltr\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>AetherOps — AI Workflow Command Center</title>\n<style>\n:root{\n  --bg:#070b16; --panel-top:#11162a; --panel-bot:#0b1020; --border:rgba(148,163,184,.12);\n  --text:#f8fafc; --muted:#94a3b8; --dim:#64748b;\n  --purple:#7c5cff; --blue:#3b82f6; --cyan:#22d3ee; --teal:#2dd4bf;\n  --green:#22c55e; --amber:#f59e0b; --red:#ef4444;\n  --grad:linear-gradient(135deg,#7c5cff,#3b82f6);\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;min-height:100%;background:var(--bg);color:var(--text);font-family:Inter,'Segoe UI',system-ui,Tahoma,sans-serif}\nbutton,input,select{font-family:inherit}\nbutton{cursor:pointer;border:0}\n.app{display:grid;grid-template-columns:232px 1fr;min-height:100vh}\n.sidebar{background:linear-gradient(180deg,#0c1122,#080c18);border-inline-end:1px solid var(--border);padding:20px 14px;display:flex;flex-direction:column;gap:16px;position:sticky;top:0;height:100vh;overflow:auto}\n.brand{display:flex;align-items:center;gap:10px;padding:4px 8px 12px}\n.cube{width:30px;height:30px;border-radius:9px;background:var(--grad);box-shadow:0 0 22px rgba(124,92,255,.45);transform:rotate(8deg);position:relative;flex:none}\n.cube:after{content:'';position:absolute;inset:7px;border-radius:4px;background:rgba(255,255,255,.28)}\n.brand b{font-size:17px;letter-spacing:.2px}\n.brand small{display:block;color:var(--dim);font-size:10px;letter-spacing:.5px}\n.nav{display:flex;flex-direction:column;gap:4px}\n.nav a{display:flex;align-items:center;gap:11px;padding:11px 12px;border-radius:11px;color:var(--muted);text-decoration:none;font-size:13px;font-weight:600;transition:.18s;border:1px solid transparent}\n.nav a:hover{background:rgba(124,92,255,.09);color:var(--text)}\n.nav a.active{background:rgba(124,92,255,.15);border-color:rgba(124,92,255,.4);color:#fff;box-shadow:0 0 20px rgba(124,92,255,.18)}\n.nav .ico{width:18px;text-align:center;font-size:15px}\n.side-card{background:linear-gradient(160deg,#151c33,#0d1324);border:1px solid var(--border);border-radius:14px;padding:13px;font-size:12px}\n.side-card h4{margin:0 0 7px;font-size:12px;display:flex;justify-content:space-between;align-items:center}\n.side-card p{margin:0;color:var(--muted);font-size:11px;line-height:1.5}\n.side-card a{color:#a78bfa;text-decoration:none;font-size:11px;font-weight:700;display:inline-block;margin-top:9px}\n.dot{width:8px;height:8px;border-radius:50%;background:var(--green);box-shadow:0 0 9px var(--green);display:inline-block}\n.mini-phone{width:38px;height:52px;border:2px solid #334155;border-radius:8px;display:flex;align-items:flex-end;gap:3px;padding:5px;float:left;margin-inline-end:9px}\n.mini-phone i{width:5px;background:var(--purple);border-radius:2px 2px 0 0;display:block}\n.main{padding:16px 24px 40px;min-width:0;overflow:hidden}\n.topbar{display:flex;align-items:center;justify-content:space-between;gap:12px;min-height:46px}\n.search{display:flex;align-items:center;gap:9px;background:#0f1526;border:1px solid var(--border);border-radius:11px;padding:8px 12px;color:var(--dim);min-width:240px;max-width:380px;flex:1}\n.search input{background:transparent;border:0;outline:0;color:var(--text);flex:1;min-width:0;font-size:12px}\n.kbd{font-size:10px;border:1px solid var(--border);border-radius:5px;padding:2px 6px;color:var(--muted)}\n.top-actions{display:flex;align-items:center;gap:12px}\n.icon-btn{width:36px;height:36px;border-radius:10px;background:#111728;border:1px solid var(--border);color:var(--text);font-size:15px;position:relative}\n.icon-btn .badge{position:absolute;top:6px;inset-inline-end:7px;width:7px;height:7px;background:var(--purple);border-radius:50%;box-shadow:0 0 8px var(--purple)}\n.profile{display:flex;align-items:center;gap:9px;background:#111728;border:1px solid var(--border);border-radius:11px;padding:5px 9px}\n.avatar{width:30px;height:30px;border-radius:50%;background:var(--grad);display:grid;place-items:center;font-size:12px;font-weight:800}\n.profile div b{display:block;font-size:11px}.profile div span{font-size:10px;color:var(--dim)}\n.page-head{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;margin:24px 0 18px;flex-wrap:wrap}\n.page-head h1{margin:0;font-size:27px;letter-spacing:-.5px}\n.page-head p{margin:7px 0 0;color:var(--muted);font-size:12px}\n.btn{background:var(--grad);color:#fff;padding:11px 18px;border-radius:11px;font-size:12px;font-weight:800;box-shadow:0 8px 24px rgba(124,92,255,.3);transition:.2s}\n.btn:hover{transform:translateY(-1px);box-shadow:0 12px 30px rgba(124,92,255,.45)}\n.btn.ghost{background:#151c30;border:1px solid var(--border);box-shadow:none}\n.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px;margin-bottom:15px}\n.metric{background:linear-gradient(180deg,var(--panel-top),var(--panel-bot));border:1px solid var(--border);border-radius:15px;padding:15px;cursor:pointer;transition:.2s;min-width:0}\n.metric:hover{border-color:rgba(124,92,255,.45);transform:translateY(-2px)}\n.metric .top{display:flex;align-items:center;gap:9px;color:var(--muted);font-size:11px;font-weight:700}\n.mi{width:28px;height:28px;border-radius:9px;display:grid;place-items:center;font-size:13px;flex:none}\n.metric .val{font-size:23px;font-weight:800;margin:9px 0 4px;white-space:nowrap}\n.trend{font-size:10px;color:var(--green)}\n.grid{display:grid;grid-template-columns:minmax(0,1.9fr) minmax(300px,1fr);gap:15px}\n.stack{display:grid;gap:15px}\n.panel{background:linear-gradient(180deg,var(--panel-top),var(--panel-bot));border:1px solid var(--border);border-radius:16px;padding:17px;min-width:0;box-shadow:0 18px 40px rgba(0,0,0,.22)}\n.ph{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:14px}\n.ph h3{margin:0;font-size:13px;display:flex;align-items:center;gap:7px}\n.ph .link{color:#a78bfa;font-size:11px;font-weight:700;background:none;text-decoration:none}\nselect.sel{background:#0d1324;color:var(--text);border:1px solid var(--border);border-radius:8px;padding:5px 9px;font-size:11px}\n.pill{font-size:10px;padding:3px 9px;border-radius:20px;font-weight:800;white-space:nowrap}\n.p-purple{background:rgba(124,92,255,.16);color:#c4b5fd}.p-green{background:rgba(34,197,94,.14);color:#86efac}.p-amber{background:rgba(245,158,11,.16);color:#fcd34d}\n.row{display:flex;align-items:center;gap:10px;padding:9px 0;border-top:1px solid rgba(148,163,184,.08)}\n.row:first-of-type{border-top:0}\n.row .ri{width:28px;height:28px;border-radius:8px;display:grid;place-items:center;flex:none;font-size:12px}\n.row .rt{flex:1;min-width:0}\n.row .rt b{font-size:11.5px;display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.row .rt small{color:var(--dim);font-size:10px}\n.row .avatar-sm{width:22px;height:22px;border-radius:50%;background:#253049;flex:none}\n.route-wrap{width:100%;overflow-x:auto}\n.route{width:100%;min-width:560px;height:210px;display:block}\n.legend{display:flex;gap:14px;flex-wrap:wrap;margin-top:10px;font-size:10px;color:var(--muted)}\n.legend i{width:9px;height:9px;border-radius:50%;display:inline-block;margin-inline-end:5px}\n.pulse{width:100%;height:150px;display:block}\n.chart-val{font-size:21px;font-weight:800}\n.chips{display:flex;gap:6px;flex-wrap:wrap;margin-top:8px}\n.chip{font-size:9px;padding:3px 7px;border-radius:6px;background:rgba(148,163,184,.1);color:var(--muted)}\n.float{position:fixed;inset-inline-end:22px;bottom:22px;width:min(320px,calc(100vw - 32px));background:rgba(24,18,48,.86);backdrop-filter:blur(16px);border:1px solid rgba(167,139,250,.35);border-radius:18px;padding:17px;box-shadow:0 20px 60px rgba(124,92,255,.28);z-index:40}\n.float h4{margin:0 0 6px;font-size:14px}.float p{margin:0 0 12px;color:#b6a8d8;font-size:11px;line-height:1.6}\n.float .btn{width:100%}\n.overlays{position:fixed;inset:0;background:rgba(3,6,15,.72);backdrop-filter:blur(4px);display:none;z-index:60;align-items:center;justify-content:center;padding:18px}\n.overlays.open{display:flex}\n.modal{background:linear-gradient(180deg,#151b31,#0b1020);border:1px solid var(--border);border-radius:18px;padding:22px;width:min(460px,100%);max-height:85vh;overflow:auto;box-shadow:0 30px 80px rgba(0,0,0,.6)}\n.modal h3{margin:0 0 8px;font-size:17px}.modal p{color:var(--muted);font-size:12px;line-height:1.7;margin:0 0 15px}\n.modal .acts{display:flex;gap:9px;justify-content:flex-end;margin-top:16px;flex-wrap:wrap}\n.toast-wrap{position:fixed;bottom:20px;left:50%;transform:translateX(-50%);z-index:80;display:flex;flex-direction:column;gap:8px;align-items:center;pointer-events:none}\n.toast{background:#132033;border:1px solid rgba(34,197,94,.4);color:#dcfce7;padding:10px 17px;border-radius:11px;font-size:12px;font-weight:700;box-shadow:0 12px 35px rgba(0,0,0,.4);animation:pop .25s ease}\n@keyframes pop{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}\n.menu{position:absolute;inset-inline-end:18px;top:56px;background:#11182b;border:1px solid var(--border);border-radius:12px;padding:7px;min-width:170px;display:none;z-index:50;box-shadow:0 18px 45px rgba(0,0,0,.5)}\n.menu.open{display:block}\n.menu button{display:block;width:100%;text-align:start;background:none;color:var(--text);padding:9px 10px;border-radius:8px;font-size:12px}\n.menu button:hover{background:rgba(124,92,255,.14)}\n.hidden{display:none!important}\n@media(max-width:1100px){.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.grid{grid-template-columns:1fr}}\n@media(max-width:720px){\n  .app{grid-template-columns:1fr}.sidebar{position:static;height:auto;flex-direction:row;flex-wrap:wrap;gap:8px;padding:12px}\n  .brand,.side-card{display:none}.nav{flex-direction:row;overflow:auto;width:100%}.nav a{white-space:nowrap;padding:8px 10px}\n  .main{padding:14px}.page-head h1{font-size:21px}.metrics{grid-template-columns:1fr 1fr;gap:9px}.metric{padding:11px}.metric .val{font-size:18px}\n  .topbar{flex-wrap:wrap}.search{min-width:100%;order:2}.profile div{display:none}\n  .float{inset-inline-end:12px;bottom:12px}\n}\n</style>\n</head>\n<body>\n<div class=\"app\">\n  <aside class=\"sidebar\">\n    <div class=\"brand\"><div class=\"cube\"></div><div><b data-i=\"brand\">AetherOps</b><small data-i=\"brandSub\">COMMAND CENTER</small></div></div>\n    <nav class=\"nav\" id=\"nav\"></nav>\n    <div class=\"side-card\">\n      <h4><span data-i=\"statusTitle\">Platform status</span><span class=\"dot\"></span></h4>\n      <p data-i=\"statusBody\">All systems operational</p>\n      <a href=\"#\" data-act=\"status\" data-i=\"statusLink\">View status →</a>\n    </div>\n    <div class=\"side-card\">\n      <div class=\"mini-phone\"><i style=\"height:14px\"></i><i style=\"height:24px\"></i><i style=\"height:18px\"></i><i style=\"height:30px\"></i></div>\n      <h4 data-i=\"mobileTitle\">ModelOps Mobile</h4>\n      <p data-i=\"mobileBody\">Monitor workflows anytime</p>\n      <a href=\"#\" data-act=\"download\" data-i=\"mobileLink\">Download app →</a>\n    </div>\n  </aside>\n\n  <main class=\"main\">\n    <div class=\"topbar\">\n      <div class=\"search\"><span>🔍</span><input id=\"search\" data-i-ph=\"searchPh\" placeholder=\"Search workflows, agents, approvals...\"><span class=\"kbd\">⌘ K</span></div>\n      <div class=\"top-actions\">\n        <button class=\"icon-btn\" data-act=\"bell\">🔔<span class=\"badge\"></span></button>\n        <button class=\"profile\" data-act=\"profile\"><span class=\"avatar\">SC</span><div><b data-i=\"profileName\">By Sarah Chen</b><span data-i=\"profileRole\">Platform Admin</span></div><span>▾</span></button>\n      </div>\n      <div class=\"menu\" id=\"profileMenu\">\n        <button data-act=\"m-profile\" data-i=\"mProfile\">Profile</button>\n        <button data-act=\"m-pref\" data-i=\"mPref\">Preferences</button>\n        <button data-act=\"lang\" data-i=\"mLang\">Language: English</button>\n        <button data-act=\"m-signout\" data-i=\"mSignout\">Sign out</button>\n      </div>\n    </div>\n\n    <div class=\"page-head\">\n      <div><h1 data-i=\"title\">AI Workflow Command Center</h1><p data-i=\"subtitle\">Monitor routing, quality, approvals, cost, and agent health in one place.</p></div>\n      <button class=\"btn\" data-act=\"console\" data-i=\"openConsole\">Open Console →</button>\n    </div>\n\n    <div class=\"metrics\" id=\"metrics\"></div>\n\n    <div class=\"grid\">\n      <div class=\"stack\">\n        <section class=\"panel\">\n          <div class=\"ph\"><h3>🔀 <span data-i=\"routeTitle\">Workflow routing map</span> <span style=\"color:var(--dim)\">ⓘ</span></h3>\n          <div><select class=\"sel\" id=\"liveSel\"><option value=\"live\" data-i=\"live\">Live</option><option value=\"24h\" data-i=\"live24\">Last 24h</option><option value=\"7d\" data-i=\"live7\">Last 7d</option></select></div></div>\n          <div class=\"route-wrap\"><svg class=\"route\" viewBox=\"0 0 720 210\" preserveAspectRatio=\"xMidYMid meet\" id=\"routeSvg\"></svg></div>\n          <div class=\"legend\">\n            <span><i style=\"background:var(--purple)\"></i><span data-i=\"primary\">Primary path</span> <b>68%</b></span>\n            <span><i style=\"background:var(--blue)\"></i><span data-i=\"secondary\">Secondary path</span> <b>22%</b></span>\n            <span><i style=\"background:var(--cyan)\"></i><span data-i=\"fallback\">Fallback path</span> <b>10%</b></span>\n          </div>\n        </section>\n        <div class=\"grid\" style=\"grid-template-columns:1fr 1fr\">\n          <section class=\"panel\"><div class=\"ph\"><h3 data-i=\"costTitle\">Cost pulse</h3><select class=\"sel\" id=\"costSel\"><option value=\"month\" data-i=\"thisMonth\">This month</option><option value=\"last\" data-i=\"lastMonth\">Last month</option><option value=\"q\" data-i=\"quarter\">This quarter</option></select></div>\n            <div class=\"chart-val\" dir=\"ltr\">$48,320</div><div class=\"trend\" data-i=\"spendTrend\">↑ 12.4% vs last month</div>\n            <svg class=\"pulse\" viewBox=\"0 0 420 150\" preserveAspectRatio=\"none\" id=\"pulseSvg\"></svg>\n          </section>\n          <section class=\"panel\"><div class=\"ph\"><h3 data-i=\"agentsTitle\">Agent health</h3><button class=\"link\" data-act=\"agents-all\" data-i=\"viewAll\">View all →</button></div><div id=\"agents\"></div></section>\n        </div>\n      </div>\n      <div class=\"stack\">\n        <section class=\"panel\"><div class=\"ph\"><h3>✅ <span data-i=\"approvalTitle\">Approval queue</span> <span class=\"pill p-purple\">3</span></h3><button class=\"link\" data-act=\"approvals-all\" data-i=\"viewAll\">View all →</button></div><div id=\"approvals\"></div></section>\n        <section class=\"panel\"><div class=\"ph\"><h3>⚠️ <span data-i=\"alertsTitle\">System alerts</span></h3><button class=\"link\" data-act=\"alerts-all\" data-i=\"viewAll\">View all →</button></div><div id=\"alerts\"></div></section>\n      </div>\n    </div>\n\n    <section class=\"panel\" style=\"margin-top:15px;grid-column:1/-1\">\n      <div class=\"ph\"><h3>🤖 RAGY Copilot</h3><span class=\"pill p-purple\" dir=\"ltr\">gemma-4 · free</span></div>\n      <p class=\"muted\" id=\"copilotNote\" style=\"font-size:11px;margin:0 0 10px\">Trained on RAGY docs · answers Arabic/English · can call automation tools.</p>\n      <div id=\"chatLog\" style=\"background:#0b0e14;border:1px solid var(--border);border-radius:10px;padding:10px;max-height:220px;overflow:auto;font-size:12px;line-height:1.7\"></div>\n      <div style=\"display:flex;gap:8px;margin-top:8px\">\n        <input id=\"chatInput\" data-i-ph=\"copilotPh\" placeholder=\"Ask: what is the MCP status?\" style=\"flex:1;background:#0b0e14;border:1px solid #2c3a56;color:#e8eef7;padding:10px;border-radius:8px\">\n        <button class=\"btn\" onclick=\"askCopilot()\">Send</button>\n      </div>\n      <pre id=\"chatRaw\" class=\"muted\" style=\"margin-top:8px;font-size:10px\"></pre>\n    </section>\n  </main>\n</div>\n\n<div class=\"float\" id=\"floatCard\"><h4 data-i=\"deployTitle\">Deploy smarter routes</h4><p data-i=\"deployBody\">Optimize performance, cost, and reliability with intelligent routing.</p><button class=\"btn\" data-act=\"deploy\" data-i=\"deployBtn\">Deploy Route ✨</button></div>\n<div class=\"overlays\" id=\"overlay\"><div class=\"modal\" id=\"modal\"></div></div>\n<div class=\"toast-wrap\" id=\"toasts\"></div>\n\n<script>\n/* ---------- i18n ---------- */\nconst I={\n en:{brand:'AetherOps',brandSub:'COMMAND CENTER',statusTitle:'Platform status',statusBody:'All systems operational',statusLink:'View status →',mobileTitle:'ModelOps Mobile',mobileBody:'Monitor workflows anytime',mobileLink:'Download app →',searchPh:'Search workflows, agents, approvals...',profileName:'By Sarah Chen',profileRole:'Platform Admin',mProfile:'Profile',mPref:'Preferences',mLang:'Language: English',mSignout:'Sign out',title:'AI Workflow Command Center',subtitle:'Monitor routing, quality, approvals, cost, and agent health in one place.',openConsole:'Open Console →',mSpend:'Monthly spend',mHealth:'Workflow health',mApproval:'Approval rate',mAgents:'Active agents',trendM:'↑ 12.4% vs last month',trendW:'↑ 2.1% vs last week',trendA:'↑ 3.4% vs last week',trendAg:'↑ 2 vs last week',routeTitle:'Workflow routing map',live:'Live',live24:'Last 24h',live7:'Last 7d',primary:'Primary path',secondary:'Secondary path',fallback:'Fallback path',costTitle:'Cost pulse',thisMonth:'This month',lastMonth:'Last month',quarter:'This quarter',spendTrend:'↑ 12.4% vs last month',agentsTitle:'Agent health',approvalTitle:'Approval queue',alertsTitle:'System alerts',viewAll:'View all →',deployTitle:'Deploy smarter routes',deployBody:'Optimize performance, cost, and reliability with intelligent routing.',deployBtn:'Deploy Route ✨',intake:'Intake',classify:'Classify',review:'Review',fallbackStage:'Fallback',deliver:'Deliver',navOverview:'Overview',navWorkflows:'Workflows',navAgents:'Agents',navAnalytics:'Analytics',navApprovals:'Approvals',navSettings:'Settings',cReview:'Contract Review',cReviewSub:'Vendor Agreement · $120,000',cInvoice:'Invoice Agent',cInvoiceSub:'Invoice #INV-2024-087 · $18,450',cSupport:'Support Copilot',cSupportSub:'Policy Update · v2.4',needs:'Needs review',approved:'Approved',escalated:'Escalated',aSupport:'Support Copilot',aDoc:'Doc Agent',aPolicy:'Policy Agent',healthy:'Healthy',alert1:'High cost spike detected',alert1d:'Invoice Agent · May 21, 2:14 PM',alert2:'Fallback volume increased',alert2d:'22% higher than usual',review:'Review',deployConfirm:'Deploy smarter routes?',deployConfirmBody:'This will create a new optimized routing definition in RAGY Cloud.',cancel:'Cancel',deploying:'Deploying...',deployOK:'Route deployed successfully',close:'Close',notice:'Notifications',noResults:'No matching results',demoNote:'Demo metrics from the reference design. Live data comes from RAGY Cloud.'},\n ar:{brand:'AetherOps',brandSub:'مركز القيادة',statusTitle:'حالة المنصة',statusBody:'جميع الأنظمة تعمل بكفاءة',statusLink:'عرض الحالة ←',mobileTitle:'تطبيق ModelOps للجوال',mobileBody:'راقب سير العمل في أي وقت',mobileLink:'تنزيل التطبيق ←',searchPh:'ابحث في سير العمل والوكلاء والموافقات...',profileName:'بواسطة سارة تشين',profileRole:'مسؤول المنصة',mProfile:'الملف الشخصي',mPref:'التفضيلات',mLang:'اللغة: العربية',mSignout:'تسجيل الخروج',title:'مركز قيادة سير العمل بالذكاء الاصطناعي',subtitle:'راقب التوجيه والجودة والموافقات والتكلفة وصحة الوكلاء في مكان واحد.',openConsole:'فتح وحدة التحكم ←',mSpend:'الإنفاق الشهري',mHealth:'صحة سير العمل',mApproval:'معدل الموافقة',mAgents:'الوكلاء النشطون',trendM:'↑ 12.4% مقارنة بالشهر الماضي',trendW:'↑ 2.1% مقارنة بالأسبوع الماضي',trendA:'↑ 3.4% مقارنة بالأسبوع الماضي',trendAg:'↑ 2 مقارنة بالأسبوع الماضي',routeTitle:'خريطة توجيه سير العمل',live:'مباشر',live24:'آخر 24 ساعة',live7:'آخر 7 أيام',primary:'المسار الأساسي',secondary:'المسار الثانوي',fallback:'مسار بديل',costTitle:'نبض التكلفة',thisMonth:'هذا الشهر',lastMonth:'الشهر الماضي',quarter:'هذا الربع',spendTrend:'↑ 12.4% مقارنة بالشهر الماضي',agentsTitle:'صحة الوكلاء',approvalTitle:'طابور الموافقات',alertsTitle:'تنبيهات النظام',viewAll:'عرض الكل ←',deployTitle:'انشر مسارات أكثر ذكاءً',deployBody:'حسّن الأداء والتكلفة والموثوقية من خلال التوجيه الذكي.',deployBtn:'نشر المسار ✨',intake:'الاستقبال',classify:'التصنيف',review:'المراجعة',fallbackStage:'المسار البديل',deliver:'التسليم',navOverview:'نظرة عامة',navWorkflows:'سير العمل',navAgents:'الوكلاء',navAnalytics:'التحليلات',navApprovals:'الموافقات',navSettings:'الإعدادات',cReview:'مراجعة العقد',cReviewSub:'اتفاقية المورد · $120,000',cInvoice:'وكيل الفواتير',cInvoiceSub:'Invoice #INV-2024-087 · $18,450',cSupport:'مساعد الدعم',cSupportSub:'تحديث السياسة · v2.4',needs:'يحتاج مراجعة',approved:'معتمد',escalated:'تم تصعيده',aSupport:'مساعد الدعم',aDoc:'وكيل المستندات',aPolicy:'وكيل السياسات',healthy:'سليم',alert1:'تم رصد ارتفاع حاد في التكلفة',alert1d:'وكيل الفواتير · 21 مايو، 2:14 م',alert2:'زيادة حجم المسار البديل',alert2d:'أعلى بنسبة 22% من المعتاد',review:'مراجعة',deployConfirm:'نشر مسارات أكثر ذكاءً؟',deployConfirmBody:'سيتم إنشاء تعريف توجيه محسّن جديد في RAGY Cloud.',cancel:'إلغاء',deploying:'جارٍ النشر...',deployOK:'تم نشر المسار بنجاح',close:'إغلاق',notice:'التنبيهات',noResults:'لا توجد نتائج مطابقة',demoNote:'مؤشرات تجريبية من التصميم المرجعي. البيانات الحية من RAGY Cloud.'}\n};\nlet LANG=localStorage.getItem('ragy_lang')||'en';\nconst t=k=>(I[LANG]||I.en)[k]||k;\nfunction askCopilot(){\n  var inp=document.getElementById('chatInput'),log=document.getElementById('chatLog');\n  var q=inp.value.trim(); if(!q)return; inp.value='';\n  log.innerHTML+='<div style=\"color:#a78bfa;margin:4px 0\">🧑 '+(LANG==='ar'?'أنت':'You')+': '+q+'</div>';\n  log.innerHTML+='<div id=\"wait\" style=\"color:#64748b;margin:4px 0\">…</div>';\n  fetch('/copilot',{method:'POST',headers:{'Authorization':'Bearer '+localStorage.getItem('ragy_token'),'Content-Type':'application/json'},body:JSON.stringify({question:q})})\n    .then(function(r){return r.json();})\n    .then(function(j){\n      var wait=document.getElementById('wait'); if(wait)wait.remove();\n      if(j.error){log.innerHTML+='<div style=\"color:#f87171;margin:4px 0\">⚠ '+j.error+'</div>';return;}\n      log.innerHTML+='<div style=\"color:#86efac;margin:4px 0 10px\">🤖 Copilot: '+String(j.answer||'').replace(/\\n/g,'<br>')+'</div>';\n      if(j.tool){log.innerHTML+='<div class=\"muted\" dir=\"ltr\" style=\"font-size:10px\">TOOL: '+j.tool.name+'</div>';}\n      document.getElementById('chatRaw').textContent=JSON.stringify(j,null,2).slice(0,1200);\n      log.scrollTop=log.scrollHeight;\n    })\n    .catch(function(e){var w=document.getElementById('wait');if(w)w.remove();log.innerHTML+='<div style=\"color:#f87171\">⚠ '+e.message+'</div>';});\n}\nfunction applyLang(){\n  document.documentElement.lang=LANG;document.documentElement.dir=LANG==='ar'?'rtl':'ltr';\n  document.querySelectorAll('[data-i]').forEach(e=>e.textContent=t(e.dataset.i));\n  document.querySelectorAll('[data-i-ph]').forEach(e=>e.placeholder=t(e.dataset.iPh));\n  const ml=document.getElementById('profileMenu').querySelector('[data-act=\"lang\"]');\n  if(ml)ml.textContent=LANG==='ar'?'Language: English':'اللغة: العربية';\n  renderNav();renderMetrics();renderApprovals();renderAgents();renderAlerts();renderRoute();renderPulse();\n}\n/* ---------- data ---------- */\nconst NAV=[['overview','navOverview','◈'],['workflows','navWorkflows','⤳'],['agents','navAgents','◉'],['analytics','navAnalytics','▥'],['approvals','navApprovals','✓'],['settings','navSettings','⚙']];\nlet ACTIVE='overview';\nfunction renderNav(){\n  document.getElementById('nav').innerHTML=NAV.map(([id,key,ic])=>`<a href=\"#\" data-nav=\"${id}\" class=\"${id===ACTIVE?'active':''}\"><span class=\"ico\">${ic}</span>${t(key)}</a>`).join('');\n}\nconst METRICS=[['mSpend','$48,320','trendM','$','#7c5cff'],['mHealth','98.6%','trendW','⌁','#3b82f6'],['mApproval','94%','trendA','✓','#2dd4bf'],['mAgents','18','trendAg','◉','#22c55e']];\nfunction renderMetrics(){\n  document.getElementById('metrics').innerHTML=METRICS.map(([k,v,tr,ic,c],i)=>`<div class=\"metric\" data-metric=\"${i}\"><div class=\"top\"><span class=\"mi\" style=\"background:${c}22;color:${c}\">${ic}</span>${t(k)}</div><div class=\"val\" dir=\"ltr\">${v}</div><div class=\"trend\">${t(tr)}</div></div>`).join('');\n}\nconst APPROVALS=[['cReview','cReviewSub','needs','p-purple','📄'],['cInvoice','cInvoiceSub','approved','p-green','✅'],['cSupport','cSupportSub','escalated','p-amber','🛡']];\nfunction renderApprovals(){\n  document.getElementById('approvals').innerHTML=APPROVALS.map(([k,s,st,cls,ic],i)=>`<div class=\"row\" data-approval=\"${i}\"><span class=\"ri\" style=\"background:${i===0?'#7c5cff22':i===1?'#22c55e22':'#f59e0b22'}\">${ic}</span><span class=\"rt\"><b>${t(k)}</b><small dir=\"ltr\">${t(s)}</small></span><span class=\"pill ${cls}\">${t(st)}</span><span class=\"avatar-sm\"></span></div>`).join('');\n}\nconst AGENTS=[['aSupport','v2.4.1 · 88.2%','#7c5cff','💬'],['aDoc','v1.8.3 · 97.1%','#3b82f6','📄'],['aPolicy','v1.6.2 · 99.0%','#2dd4bf','🛡']];\nfunction renderAgents(){\n  document.getElementById('agents').innerHTML=AGENTS.map(([k,v,c,ic],i)=>`<div class=\"row\" data-agent=\"${i}\"><span class=\"ri\" style=\"background:${c}22\">${ic}</span><span class=\"rt\"><b>${t(k)}</b><small dir=\"ltr\">${v}</small></span><span class=\"pill p-green\">${t('healthy')}</span><svg width=\"46\" height=\"18\" viewBox=\"0 0 46 18\"><polyline points=\"0,14 8,11 16,13 24,7 32,9 40,3 46,5\" fill=\"none\" stroke=\"#22c55e\" stroke-width=\"2\"/></svg></div>`).join('');\n}\nconst ALERTS=[['alert1','alert1d','⚠','#f59e0b'],['alert2','alert2d','ⓘ','#3b82f6']];\nfunction renderAlerts(){\n  document.getElementById('alerts').innerHTML=ALERTS.map(([k,d,ic,c],i)=>`<div class=\"row\"><span class=\"ri\" style=\"background:${c}22;color:${c}\">${ic}</span><span class=\"rt\"><b>${t(k)}</b><small>${t(d)}</small></span><button class=\"btn ghost\" style=\"padding:6px 10px;font-size:10px\" data-alert=\"${i}\">${t('review')}</button></div>`).join('');\n}\n/* ---------- svg charts ---------- */\nfunction renderRoute(){\n  const stages=[['intake',60],['classify',190],['review',330],['fallbackStage',470],['deliver',620]];\n  let s='';\n  stages.forEach(([key,x],i)=>{\n    s+=`<text x=\"${x}\" y=\"20\" text-anchor=\"middle\" fill=\"#94a3b8\" font-size=\"11\" font-weight=\"700\">${t(key)}</text>`;\n    s+=`<rect x=\"${x-7}\" y=\"34\" width=\"14\" height=\"140\" rx=\"7\" fill=\"${i===4?'#7c5cff':'#1e293b'}\" opacity=\"${i===4?.9:1}\"/>`;\n    s+=`<rect x=\"${x-3}\" y=\"38\" width=\"6\" height=\"132\" rx=\"3\" fill=\"${i===4?'#a78bfa':i===3?'#22d3ee':'#7c5cff'}\" opacity=\".55\"/>`;\n  });\n  const paths=[[60,190,'#7c5cff','68%'],[190,330,'#7c5cff','72%'],[330,470,'#3b82f6','46%'],[470,620,'#22d3ee','91%']];\n  paths.forEach(([x1,x2,c,label],i)=>{\n    const y=70+i*28;\n    s+=`<path d=\"M ${x1+8} ${y} C ${x1+70} ${y-28}, ${x2-70} ${y+28}, ${x2-8} ${y}\" fill=\"none\" stroke=\"${c}\" stroke-width=\"2.5\" opacity=\".85\"/>`;\n    s+=`<text x=\"${(x1+x2)/2}\" y=\"${y-14}\" text-anchor=\"middle\" fill=\"${c}\" font-size=\"10\" font-weight=\"800\">${label}</text>`;\n  });\n  s+=`<circle cx=\"628\" cy=\"104\" r=\"18\" fill=\"none\" stroke=\"#a78bfa\" stroke-width=\"2\"/><text x=\"628\" y=\"109\" text-anchor=\"middle\" fill=\"#a78bfa\" font-size=\"16\">✓</text>`;\n  s+=`<circle cx=\"478\" cy=\"154\" r=\"8\" fill=\"none\" stroke=\"#22d3ee\" stroke-width=\"2\"/>`;\n  document.getElementById('routeSvg').innerHTML=s;\n}\nfunction renderPulse(){\n  const pts=[[0,120],[40,100],[80,112],[120,72],[160,88],[200,52],[240,78],[280,42],[320,66],[360,30],[400,55]];\n  let s='';\n  [30,60,90,120].forEach((y,i)=>s+=`<line x1=\"0\" y1=\"${y}\" x2=\"420\" y2=\"${y}\" stroke=\"#233\" stroke-width=\"1\"/><text x=\"2\" y=\"${y-4}\" fill=\"#64748b\" font-size=\"9\">$${20-i*5}K</text>`);\n  s+=`<polygon points=\"0,150 ${pts.map(p=>p.join(',')).join(' ')} 420,150\" fill=\"rgba(124,92,255,.18)\"/>`;\n  s+=`<polyline points=\"${pts.map(p=>p.join(',')).join(' ')}\" fill=\"none\" stroke=\"#7c5cff\" stroke-width=\"2.5\"/>`;\n  pts.forEach(([x,y])=>s+=`<rect x=\"${x-3}\" y=\"${y}\" width=\"6\" height=\"${150-y}\" fill=\"#7c5cff\" opacity=\".3\"/>`);\n  s+=`<circle cx=\"360\" cy=\"30\" r=\"4\" fill=\"#22d3ee\"/><text x=\"332\" y=\"22\" fill=\"#22d3ee\" font-size=\"9\">May 26 · $2,640</text>`;\n  document.getElementById('pulseSvg').innerHTML=s;\n}\n/* ---------- interactions ---------- */\nfunction toast(msg){const d=document.createElement('div');d.className='toast';d.textContent=msg;document.getElementById('toasts').appendChild(d);setTimeout(()=>d.remove(),2800);}\nfunction openModal(html){document.getElementById('modal').innerHTML=html;document.getElementById('overlay').classList.add('open');}\nfunction closeModal(){document.getElementById('overlay').classList.remove('open');}\ndocument.addEventListener('click',e=>{\n  const nav=e.target.closest('[data-nav]');\n  if(nav){e.preventDefault();ACTIVE=nav.dataset.nav;renderNav();toast(t('navOverview')+' → '+t(NAV.find(n=>n[0]===ACTIVE)[1]));return;}\n  const m=e.target.closest('[data-metric]');\n  if(m){const i=+m.dataset.metric;toast(['Cost pulse','Workflow routing map','Approval queue','Agent health'][i]);return;}\n  const ap=e.target.closest('[data-approval]');\n  if(ap){const i=+ap.dataset.approval;openModal(`<h3>${t(APPROVALS[i][0])}</h3><p dir=\"ltr\">${t(APPROVALS[i][1])}</p><p>${t(APPROVALS[i][2])}</p><div class=\"acts\"><button class=\"btn ghost\" data-act=\"close\">${t('close')}</button><button class=\"btn\" data-act=\"ok\" data-msg=\"${t('approved')}\">${t('review')}</button></div>`);return;}\n  const ag=e.target.closest('[data-agent]');\n  if(ag){const i=+ag.dataset.agent;openModal(`<h3>${t(AGENTS[i][0])}</h3><p dir=\"ltr\">${AGENTS[i][1]}</p><p>${t('healthy')} · ${t('demoNote')}</p><div class=\"acts\"><button class=\"btn\" data-act=\"close\">${t('close')}</button></div>`);return;}\n  const al=e.target.closest('[data-alert]');\n  if(al){const i=+al.dataset.alert;openModal(`<h3>${t(ALERTS[i][0])}</h3><p>${t(ALERTS[i][1])}</p><div class=\"acts\"><button class=\"btn ghost\" data-act=\"close\">${t('close')}</button><button class=\"btn\" data-act=\"ok\" data-msg=\"${t('review')}\">${t('review')}</button></div>`);return;}\n  const a=e.target.closest('[data-act]');\n  if(!a)return;\n  const act=a.dataset.act;\n  if(act==='lang'){LANG=LANG==='en'?'ar':'en';localStorage.setItem('ragy_lang',LANG);document.getElementById('profileMenu').classList.remove('open');applyLang();toast(LANG==='ar'?'تم التحويل للعربية':'Switched to English');return;}\n  if(act==='profile'){document.getElementById('profileMenu').classList.toggle('open');return;}\n  if(act==='bell'){openModal(`<h3>${t('notice')}</h3><p>${t('alert1')} — ${t('alert1d')}</p><p>${t('alert2')} — ${t('alert2d')}</p><div class=\"acts\"><button class=\"btn\" data-act=\"close\">${t('close')}</button></div>`);return;}\n  if(act==='close'){closeModal();return;}\n  if(act==='ok'){closeModal();toast(a.dataset.msg||'OK');return;}\n  if(act==='deploy'){\n    openModal(`<h3>${t('deployConfirm')}</h3><p>${t('deployConfirmBody')}</p><div class=\"acts\"><button class=\"btn ghost\" data-act=\"close\">${t('cancel')}</button><button class=\"btn\" data-act=\"do-deploy\">${t('deployBtn')}</button></div>`);\n    return;\n  }\n  if(act==='do-deploy'){\n    a.textContent=t('deploying');a.disabled=true;\n    setTimeout(()=>{closeModal();toast(t('deployOK'));},700);\n    return;\n  }\n  if(act==='console'){toast(LANG==='ar'?'افتح /app في اللوحة السحابية':'Open /app in the cloud console');return;}\n  if(act==='status'){openModal(`<h3>${t('statusTitle')}</h3><p>${t('statusBody')} · RAGY Cloud Engine <span dir=\"ltr\">ready:true</span></p><div class=\"acts\"><button class=\"btn\" data-act=\"close\">${t('close')}</button></div>`);return;}\n  if(act==='download'){openModal(`<h3>${t('mobileTitle')}</h3><p>${t('mobileBody')} — ${t('demoNote')}</p><div class=\"acts\"><button class=\"btn\" data-act=\"close\">${t('close')}</button></div>`);return;}\n  if(act==='m-profile'||act==='m-pref'||act==='m-signout'){document.getElementById('profileMenu').classList.remove('open');toast(t(act==='m-profile'?'mProfile':act==='m-pref'?'mPref':'mSignout'));return;}\n  if(act==='approvals-all'||act==='agents-all'||act==='alerts-all'){toast(t('viewAll').replace(' →','').replace('←',''));return;}\n});\ndocument.getElementById('overlay').addEventListener('click',e=>{if(e.target.id==='overlay')closeModal();});\ndocument.addEventListener('keydown',e=>{\n  if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.getElementById('search').focus();}\n  if(e.key==='Escape'){closeModal();document.getElementById('profileMenu').classList.remove('open');}\n});\ndocument.getElementById('search').addEventListener('input',e=>{\n  const q=e.target.value.trim().toLowerCase();\n  if(!q)return;\n  const all=[...Object.values(I[LANG])].filter(v=>typeof v==='string');\n  if(!all.some(v=>v.toLowerCase().includes(q)))toast(t('noResults'));\n});\ndocument.getElementById('liveSel').addEventListener('change',e=>toast(t(e.target.value==='live'?'live':e.target.value==='24h'?'live24':'live7')));\ndocument.getElementById('costSel').addEventListener('change',e=>toast(t(e.target.value==='month'?'thisMonth':e.target.value==='last'?'lastMonth':'quarter')));\napplyLang();\n</script>\n</body>\n</html>\n";
